-- ============================================================
-- STEP 2: Create the transfer_parts PostgreSQL function
-- ============================================================
CREATE OR REPLACE FUNCTION transfer_parts(
    source_inventory_id   INTEGER,
    target_inventory_id   INTEGER,
    part_to_transfer_num  VARCHAR,
    color_to_transfer_id  INTEGER,
    quantity_to_transfer  INTEGER,
    transfer_reason       VARCHAR DEFAULT 'manual_transfer'
) RETURNS TEXT
LANGUAGE plpgsql
AS $$
DECLARE
    -- Existence / quantity variables
    v_source_exists       INTEGER;
    v_target_exists       INTEGER;
    v_part_exists         INTEGER;
    v_color_exists        INTEGER;
    v_source_qty          INTEGER;
    v_source_is_spare     BOOLEAN;
    v_target_record_exists INTEGER;
    v_success_msg         TEXT;
    v_error_msg           TEXT;
BEGIN
    -- ==============================================================
    -- VALIDATION B1: Minimum quantity
    -- ==============================================================
    IF quantity_to_transfer < 1 THEN
        v_error_msg := 'Transfer quantity must be at least 1. Provided: ' || quantity_to_transfer;
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id,
            part_num, color_id, quantity_transferred,
            transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id,
            part_to_transfer_num, color_to_transfer_id, quantity_to_transfer,
            transfer_reason, 'failed', v_error_msg
        );
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- ==============================================================
    -- VALIDATION B2: Maximum quantity (500)
    -- ==============================================================
    IF quantity_to_transfer > 500 THEN
        v_error_msg := 'Transfer quantity exceeds maximum allowed (500). Provided: ' || quantity_to_transfer;
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id,
            part_num, color_id, quantity_transferred,
            transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id,
            part_to_transfer_num, color_to_transfer_id, quantity_to_transfer,
            transfer_reason, 'failed', v_error_msg
        );
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- ==============================================================
    -- VALIDATION A / B3: Self-transfer prevention
    -- ==============================================================
    IF source_inventory_id = target_inventory_id THEN
        v_error_msg := 'Self-transfer not allowed: source and target inventory IDs are identical (' || source_inventory_id || ').';
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id,
            part_num, color_id, quantity_transferred,
            transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id,
            part_to_transfer_num, color_to_transfer_id, quantity_to_transfer,
            transfer_reason, 'failed', v_error_msg
        );
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- ==============================================================
    -- VALIDATION A: Source inventory exists
    -- ==============================================================
    SELECT COUNT(*) INTO v_source_exists
    FROM lego_inventories
    WHERE id = source_inventory_id;

    IF v_source_exists = 0 THEN
        v_error_msg := 'Source inventory ID ' || source_inventory_id || ' does not exist in lego_inventories.';
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id,
            part_num, color_id, quantity_transferred,
            transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id,
            part_to_transfer_num, color_to_transfer_id, quantity_to_transfer,
            transfer_reason, 'failed', v_error_msg
        );
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- ==============================================================
    -- VALIDATION A: Target inventory exists
    -- ==============================================================
    SELECT COUNT(*) INTO v_target_exists
    FROM lego_inventories
    WHERE id = target_inventory_id;

    IF v_target_exists = 0 THEN
        v_error_msg := 'Target inventory ID ' || target_inventory_id || ' does not exist in lego_inventories.';
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id,
            part_num, color_id, quantity_transferred,
            transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id,
            part_to_transfer_num, color_to_transfer_id, quantity_to_transfer,
            transfer_reason, 'failed', v_error_msg
        );
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- ==============================================================
    -- VALIDATION A: Part exists in lego_parts
    -- ==============================================================
    SELECT COUNT(*) INTO v_part_exists
    FROM lego_parts
    WHERE part_num = part_to_transfer_num;

    IF v_part_exists = 0 THEN
        v_error_msg := 'Part number "' || part_to_transfer_num || '" does not exist in lego_parts.';
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id,
            part_num, color_id, quantity_transferred,
            transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id,
            part_to_transfer_num, color_to_transfer_id, quantity_to_transfer,
            transfer_reason, 'failed', v_error_msg
        );
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- ==============================================================
    -- VALIDATION A: Color exists in lego_colors
    -- ==============================================================
    SELECT COUNT(*) INTO v_color_exists
    FROM lego_colors
    WHERE id = color_to_transfer_id;

    IF v_color_exists = 0 THEN
        v_error_msg := 'Color ID ' || color_to_transfer_id || ' does not exist in lego_colors.';
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id,
            part_num, color_id, quantity_transferred,
            transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id,
            part_to_transfer_num, color_to_transfer_id, quantity_to_transfer,
            transfer_reason, 'failed', v_error_msg
        );
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- ==============================================================
    -- STEP A: Lock source & target inventory rows to prevent race
    --         conditions (SELECT ... FOR UPDATE)
    -- ==============================================================
    PERFORM id
    FROM lego_inventories
    WHERE id IN (source_inventory_id, target_inventory_id)
    ORDER BY id          -- consistent ordering avoids deadlocks
    FOR UPDATE;

    -- ==============================================================
    -- VALIDATION A: Source has the part with sufficient quantity
    --               (regular + spare parts combined)
    -- ==============================================================
    SELECT COALESCE(SUM(quantity), 0)
    INTO v_source_qty
    FROM lego_inventory_parts
    WHERE inventory_id = source_inventory_id
      AND part_num     = part_to_transfer_num
      AND color_id     = color_to_transfer_id;

    IF v_source_qty = 0 THEN
        v_error_msg := 'Part "' || part_to_transfer_num || '" with color_id ' || color_to_transfer_id ||
                       ' not found in source inventory ' || source_inventory_id || '.';
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id,
            part_num, color_id, quantity_transferred,
            transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id,
            part_to_transfer_num, color_to_transfer_id, quantity_to_transfer,
            transfer_reason, 'failed', v_error_msg
        );
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    IF v_source_qty < quantity_to_transfer THEN
        v_error_msg := 'Insufficient quantity in source inventory ' || source_inventory_id ||
                       '. Available: ' || v_source_qty ||
                       ', Requested: ' || quantity_to_transfer ||
                       ' (part: "' || part_to_transfer_num || '", color_id: ' || color_to_transfer_id || ').';
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id,
            part_num, color_id, quantity_transferred,
            transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id,
            part_to_transfer_num, color_to_transfer_id, quantity_to_transfer,
            transfer_reason, 'failed', v_error_msg
        );
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- Capture is_spare flag from the source row (non-spare preferred)
    SELECT is_spare
    INTO v_source_is_spare
    FROM lego_inventory_parts
    WHERE inventory_id = source_inventory_id
      AND part_num     = part_to_transfer_num
      AND color_id     = color_to_transfer_id
    ORDER BY is_spare   -- FALSE sorts before TRUE → prefer non-spare
    LIMIT 1;

    -- ==============================================================
    -- STEP B: Deduct from source inventory
    --         Decrement quantity; delete row when it reaches zero
    -- ==============================================================
    UPDATE lego_inventory_parts
    SET quantity = quantity - quantity_to_transfer
    WHERE inventory_id = source_inventory_id
      AND part_num     = part_to_transfer_num
      AND color_id     = color_to_transfer_id
      AND is_spare     = v_source_is_spare;

    -- Remove the row entirely if quantity has been exhausted
    DELETE FROM lego_inventory_parts
    WHERE inventory_id = source_inventory_id
      AND part_num     = part_to_transfer_num
      AND color_id     = color_to_transfer_id
      AND is_spare     = v_source_is_spare
      AND quantity     = 0;

    -- ==============================================================
    -- STEP C: Credit target inventory
    --         If part/color already exists → increment quantity
    --         Otherwise → insert new record
    -- ==============================================================
    SELECT COUNT(*) INTO v_target_record_exists
    FROM lego_inventory_parts
    WHERE inventory_id = target_inventory_id
      AND part_num     = part_to_transfer_num
      AND color_id     = color_to_transfer_id
      AND is_spare     = v_source_is_spare;

    IF v_target_record_exists > 0 THEN
        -- Record exists → just increment quantity
        UPDATE lego_inventory_parts
        SET quantity = quantity + quantity_to_transfer
        WHERE inventory_id = target_inventory_id
          AND part_num     = part_to_transfer_num
          AND color_id     = color_to_transfer_id
          AND is_spare     = v_source_is_spare;
    ELSE
        -- No matching record → insert new row preserving is_spare flag
        INSERT INTO lego_inventory_parts
            (inventory_id, part_num, color_id, quantity, is_spare)
        VALUES
            (target_inventory_id, part_to_transfer_num, color_to_transfer_id,
             quantity_to_transfer, v_source_is_spare);
    END IF;

    -- ==============================================================
    -- STEP D: Audit log — success
    -- ==============================================================
    v_success_msg := 'Successfully transferred ' || quantity_to_transfer ||
                     ' parts (' || part_to_transfer_num ||
                     ', color_id: ' || color_to_transfer_id ||
                     ') from inventory ' || source_inventory_id ||
                     ' to inventory '   || target_inventory_id ||
                     '. Reason: '       || transfer_reason;

    INSERT INTO inventory_transfer_log (
        source_inventory_id, target_inventory_id,
        part_num, color_id, quantity_transferred,
        transfer_reason, transfer_status, error_message
    ) VALUES (
        source_inventory_id, target_inventory_id,
        part_to_transfer_num, color_to_transfer_id, quantity_to_transfer,
        transfer_reason, 'success', NULL
    );

    RETURN v_success_msg;

EXCEPTION
    WHEN OTHERS THEN
        -- Re-raise the exception so the caller receives the message
        -- (audit INSERT for failures happens inside each validation block
        --  BEFORE the RAISE, so it is already committed implicitly
        --  via the exception handler unwinding the subtransaction)
        RAISE;
END;
$$;

SELECT 'transfer_parts function created successfully' AS result;
"}

